#include "wifi_communication.h"
#include "wifi_env.h"  // Generated by PlatformIO from the local .env file.

#include <Arduino.h>
#include <ESPmDNS.h>
#include <WebServer.h>
#include <WiFi.h>
#include <WiFiManager.h>
#include <WiFiUdp.h>
#include <string.h>

namespace {
// The browser requests the worker API over normal HTTP (port 80). The UDP
// beacon is sent separately so local network tools can spot this ESP32.
constexpr uint16_t HTTP_PORT = 80;
constexpr uint16_t DISCOVERY_PORT = 4210;
constexpr uint32_t BEACON_INTERVAL_MS = 2000;
constexpr uint32_t WIFI_RETRY_INTERVAL_MS = 10000;
constexpr char MDNS_HOST[] = "shieldguard";

WebServer httpServer(HTTP_PORT);
WiFiUDP discoveryUdp;
WiFiManager wifiManager;
bool networkServicesStarted = false;
bool setupPortalAttempted = false;
uint32_t connectionStartedAt = 0;
IMUData currentSensorData{};
bool currentImuAvailable = false;
bool currentFallDetected = false;
bool currentSosState = false;
const char* currentAlarmState = "NORMAL";
uint32_t lastBeaconAt = 0;
uint32_t lastWifiRetryAt = 0;

void addCorsHeaders() {
    // GitHub Pages and the ESP32 have different web addresses (origins). These
    // headers let the browser page read this device's response. They do not
    // bypass the browser's separate local-network permission prompt.
    httpServer.sendHeader("Access-Control-Allow-Origin", "*");
    httpServer.sendHeader("Access-Control-Allow-Methods", "GET, OPTIONS");
    httpServer.sendHeader("Access-Control-Allow-Headers", "Content-Type, Accept");
    httpServer.sendHeader("Access-Control-Allow-Private-Network", "true");
    httpServer.sendHeader("Cache-Control", "no-store, max-age=0");
}

void handlePreflight() {
    addCorsHeaders();
    httpServer.send(204);
}

void handleHealth() {
    addCorsHeaders();
    httpServer.send(200, "application/json",
                    "{\"service\":\"shieldguard\",\"connected\":true,\"workerCount\":1}");
}

void handleWorkerData() {
    char body[700];
    char sensorTemperature[24];
    char accX[24], accY[24], accZ[24];
    char gyroX[24], gyroY[24], gyroZ[24];

    // Send null for missing IMU readings rather than displaying fake zeroes.
    if (currentImuAvailable) {
        snprintf(sensorTemperature, sizeof(sensorTemperature), "%.2f", currentSensorData.temp);
        snprintf(accX, sizeof(accX), "%.3f", currentSensorData.accX);
        snprintf(accY, sizeof(accY), "%.3f", currentSensorData.accY);
        snprintf(accZ, sizeof(accZ), "%.3f", currentSensorData.accZ);
        snprintf(gyroX, sizeof(gyroX), "%.3f", currentSensorData.gyroX);
        snprintf(gyroY, sizeof(gyroY), "%.3f", currentSensorData.gyroY);
        snprintf(gyroZ, sizeof(gyroZ), "%.3f", currentSensorData.gyroZ);
    } else {
        strcpy(sensorTemperature, "null");
        strcpy(accX, "null"); strcpy(accY, "null"); strcpy(accZ, "null");
        strcpy(gyroX, "null"); strcpy(gyroY, "null"); strcpy(gyroZ, "null");
    }

    // temperatureC is null because the MPU6050 does not measure body temperature.
    const int length = snprintf(
        body,
        sizeof(body),
        "{\"workers\":[{\"id\":\"1\",\"workerId\":\"1\",\"name\":\"Worker #1\",\"active\":true,\"imuAvailable\":%s,\"temperatureC\":null,\"sensorTemperatureC\":%s,\"acceleration\":{\"x\":%s,\"y\":%s,\"z\":%s},\"gyroscope\":{\"x\":%s,\"y\":%s,\"z\":%s},\"fallDetected\":%s,\"sos\":%s,\"alarmState\":\"%s\",\"updatedAtMs\":%lu}]}",
        currentImuAvailable ? "true" : "false",
        sensorTemperature, accX, accY, accZ, gyroX, gyroY, gyroZ,
        currentFallDetected ? "true" : "false",
        currentSosState ? "true" : "false",
        currentAlarmState,
        static_cast<unsigned long>(millis()));

    addCorsHeaders();
    if (length <= 0 || length >= static_cast<int>(sizeof(body))) {
        httpServer.send(500, "application/json",
                        "{\"error\":\"response serialization failed\"}");
        return;
    }
    httpServer.send(200, "application/json", body);
}

void startHttpService() {
    // Each route is a small URL handled by the ESP32:
    // GET /api/data returns readings; GET /api/health is a simple connection check.
    httpServer.on("/api/data", HTTP_GET, handleWorkerData);
    httpServer.on("/api/data", HTTP_OPTIONS, handlePreflight);
    httpServer.on("/api/health", HTTP_GET, handleHealth);
    httpServer.on("/api/health", HTTP_OPTIONS, handlePreflight);
    httpServer.onNotFound([]() {
        addCorsHeaders();
        httpServer.send(404, "application/json", "{\"error\":\"not found\"}");
    });
    httpServer.begin();
    Serial.printf("HTTP API: http://%s.local/api/data and http://%s/api/data\n",
                  MDNS_HOST, WiFi.localIP().toString().c_str());
}

void sendDiscoveryBeacon() {
    const IPAddress ip = WiFi.localIP();
    const IPAddress subnetMask = WiFi.subnetMask();
    IPAddress broadcastIp = ip;
    for (uint8_t octet = 0; octet < 4; ++octet) {
        const uint8_t hostMask = static_cast<uint8_t>(~subnetMask[octet]);
        broadcastIp[octet] = static_cast<uint8_t>((ip[octet] & subnetMask[octet]) | hostMask);
    }

    char beacon[180];
    snprintf(beacon, sizeof(beacon),
             "{\"service\":\"shieldguard\",\"host\":\"%s.local\",\"ip\":\"%u.%u.%u.%u\",\"port\":%u,\"workerId\":\"1\"}",
             MDNS_HOST, ip[0], ip[1], ip[2], ip[3], HTTP_PORT);

    // Announce the device to other programs on this Wi-Fi subnet. Browsers
    // cannot listen for UDP directly, so the dashboard finds this node by mDNS.
    discoveryUdp.beginPacket(broadcastIp, DISCOVERY_PORT);
    discoveryUdp.write(reinterpret_cast<const uint8_t *>(beacon), strlen(beacon));
    discoveryUdp.endPacket();
}

void connectToWifi() {
    WiFi.mode(WIFI_STA);
    WiFi.setHostname(MDNS_HOST);
    WiFi.setAutoReconnect(true);

    // Start connecting and return. The main loop must keep reading f/r and
    // updating alarms while the network is unavailable.
    wifiManager.setConfigPortalBlocking(false);
    wifiManager.setConfigPortalTimeout(300);
    wifiManager.setSaveConnectTimeout(5);
    wifiManager.setConnectRetries(1);
    connectionStartedAt = millis();
    if (WIFI_ENV_SSID[0] != '\0') {
        Serial.println("Connecting to the Wi-Fi network configured in .env...");
        WiFi.begin(WIFI_ENV_SSID, WIFI_ENV_PASSWORD);
    } else {
        Serial.println("Connecting to saved Wi-Fi...");
        WiFi.begin();
    }
}

void startSetupPortal() {
    const String macAddress = WiFi.macAddress();
    const String suffix = macAddress.substring(9, 17);
    const String setupSsid = "ShieldGuard-Setup-" + suffix;
    const String setupPassword = "SG-" + suffix + "-Pair";
    Serial.println("Wi-Fi not connected. Opening setup portal; serial alarms remain available.");
    Serial.printf("Setup Wi-Fi: %s\nSetup password: %s\n", setupSsid.c_str(), setupPassword.c_str());
    wifiManager.startConfigPortal(setupSsid.c_str(), setupPassword.c_str());
}

void startNetworkServices() {
    // mDNS translates shieldguard.local into the ESP32's current local IP.
    if (MDNS.begin(MDNS_HOST)) {
        MDNS.addService("http", "tcp", HTTP_PORT);
        MDNS.addServiceTxt("http", "tcp", "path", "/api/data");
        Serial.printf("mDNS discovery: http://%s.local/api/data\n", MDNS_HOST);
    } else {
        Serial.println("mDNS startup failed; use the printed ESP32 IP address.");
    }
    discoveryUdp.begin(DISCOVERY_PORT + 1);
    startHttpService();
    networkServicesStarted = true;
}
}  // namespace

void WifiCommunication::begin() {
    connectToWifi();
}

void WifiCommunication::update(const IMUData& sensorData, bool imuAvailable,
                               bool fallDetected, bool sosActive, const char* alarmState) {
    // The browser receives a snapshot of the latest alarm and sensor state.
    currentSensorData = sensorData;
    currentImuAvailable = imuAvailable;
    currentFallDetected = fallDetected;
    currentSosState = sosActive;
    currentAlarmState = alarmState ? alarmState : "NORMAL";

    // Process portal requests between alarm updates. Saving Wi-Fi credentials
    // can briefly wait for the submitted network, bounded by the save timeout.
    if (wifiManager.getConfigPortalActive()) wifiManager.process();

    const uint32_t now = millis();
    if (WiFi.status() == WL_CONNECTED) {
        // Both servers use port 80: close the portal before starting the API.
        if (wifiManager.getConfigPortalActive()) wifiManager.stopConfigPortal();
        if (!networkServicesStarted) {
            Serial.printf("Connected to Wi-Fi. ESP32 IP: %s\n", WiFi.localIP().toString().c_str());
            startNetworkServices();
        }
        httpServer.handleClient();
        if (now - lastBeaconAt >= BEACON_INTERVAL_MS) {
            lastBeaconAt = now;
            sendDiscoveryBeacon();
        }
    } else if (!networkServicesStarted && !setupPortalAttempted && now - connectionStartedAt >= 20000) {
        setupPortalAttempted = true;
        startSetupPortal();
        lastWifiRetryAt = now;
    } else if (!wifiManager.getConfigPortalActive()
               && (networkServicesStarted || setupPortalAttempted)
               && now - lastWifiRetryAt >= WIFI_RETRY_INTERVAL_MS) {
        // A connection failure or portal timeout must not reboot the ESP32
        // and interrupt the serial fall demo. Retry while alarms keep running.
        lastWifiRetryAt = now;
        Serial.println("Wi-Fi disconnected; retrying. Serial commands still work.");
        WiFi.mode(WIFI_STA);
        WiFi.reconnect();
    }
}